pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Primary objective: Best-Fit Decreasing logic, penalized by residual space.
    // We favor smaller post_residuals (tighter packing).
    let mut score = post.powf(1.5);

    // Penalty for creating "dead space": if the residual is small but too large to fit the average next item.
    // We estimate the difficulty of filling the remaining space based on mean_residual.
    if post > 0.0 && post < 20.0 {
        score += (20.0 - post).powi(2) * 2.0;
    }

    // Lookahead coupling: If the next item is large, penalize small residuals that cannot accommodate it.
    if next_item_size > 0 && post < next_item_size as f64 {
        score += (next_item_size as f64 - post) * 5.0;
    }

    // Stream progression: As we approach the end of the stream, prioritize closing bins over opening new ones.
    // If this is a new bin (post == bin_capacity - item_size), increase cost as progress increases.
    if bin_residual == bin_capacity {
        score += 15.0 + (progress * 100.0);
    }

    // If this is the last fitting bin available, heavily reward placing it here to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Interaction with mean_residual: If our current bin is significantly worse than the average, penalize it.
    if post > mean_residual {
        score += (post - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Harmonic Penalty: Heavily penalize residuals that are small but cannot fit likely future items.
    // If post_residual is < 10, it's "dead space" unless it is exactly 0.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // 2. Lookahead Coupling: If the next item is large, favor bins that leave enough room for it.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalize bins that cannot accommodate the next item (blocking potential sequence).
            score += 30.0;
        } else {
            // Reward bins that can accommodate the next item.
            score -= 15.0;
        }
    }

    // 3. Density Balancing: Avoid opening new bins if existing bins have high occupancy.
    // We want to force usage of open bins when fitting_bins_count > 0.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // High penalty for opening a new bin if an existing bin could fit it.
            score += 60.0 + (open_bins_count as f64 * 2.0);
        } else {
            // Baseline cost for new bin.
            score += 10.0;
        }
    }

    // 4. Modulo/Harmonic refinement: Favor residuals that align with common item sizes (multiples of 10).
    // This helps keep "clean" space for future items.
    let remainder = post_residual % 10;
    if remainder == 0 {
        score -= 5.0;
    } else {
        score += remainder as f64 * 1.5;
    }

    // 5. Progression scaling: As we approach the end of the stream, prioritize closing bins.
    let progress = step_index as f64 / total_items as f64;
    score += progress * 20.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Best-Fit logic: penalize large post_residuals to keep bins packed tightly.
    // 2. Lookahead optimization: If post_residual is close to next_item_size, reward this bin heavily.
    if next_item_size > 0 {
        let diff = (post_residual as f64 - next_item_size as f64).abs();
        if post_residual >= next_item_size {
            // Perfect or near-perfect match for next item
            score -= (100.0 - diff) * 2.5;
        } else {
            // Cannot fit next item, penalize significantly
            score += 50.0;
        }
    }

    // 3. Prevent fragmentation: Penalize bins that leave very small, unusable remainders.
    // Generally, residuals < 10 are difficult to fill.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 4. Strategic new-bin thresholding:
    // If this is an empty bin (new bin candidate), only select if it's better than 
    // the current best fit, weighted by how many bins are already open.
    if bin_residual == bin_capacity {
        // High penalty for opening new bins early in the stream.
        score += 30.0 + (step_index as f64 / total_items as f64) * 20.0;
    }

    // 5. Mean residual balancing:
    // Favor bins that keep the overall mean residual stable to prevent outlier bins.
    let dev_from_mean = (post_residual as f64 - mean_residual).abs();
    score += dev_from_mean * 0.5;

    // 6. Last-resort handling:
    // If this is the only bin that can fit the item, prioritize it strongly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base heuristic: Minimize post_residual (Best Fit)
    // Weight the post_residual by the proximity to the bin capacity to discourage 
    // creating small, unusable gaps.
    let mut score = post * (1.0 + (100.0 - post) / 100.0);

    // Penalty for creating a new bin:
    // If this is a new bin (bin_residual == bin_capacity), apply a dynamic cost.
    // As the stream progresses, we become more conservative about opening new bins.
    if bin_residual == bin_capacity {
        score += 35.0 + (45.0 * progress);
    }

    // Lookahead coupling:
    // If the next item exists, favor placements that leave enough space for it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            // Penalize placements that squeeze out the next item
            score += (next_item_size as f64 - post) * 1.5;
        } else {
            // Reward placements that fit the next item perfectly (Best Fit for Lookahead)
            score -= (post - next_item_size as f64) * 0.5;
        }
    }

    // Global state coupling:
    // Avoid creating too many bins if the average residual is already high.
    // This stabilizes the distribution of items across existing open bins.
    if open_bins_count > 0 {
        score += (mean_residual - post) * 0.2;
    }

    // Fitting density:
    // If this is the only bin that can fit the item, prioritize it heavily
    // to prevent unnecessary overflow or bin creation.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    score
}
